<?php if($list):?><?php if($settingsCanEditOperations):?><section class="card"><details class="settings-entry" data-settings-entry><summary>Add Area</summary><form method="post" class="stay-form" data-settings-editor><?php stay_fields('area_catalogue',0,['area_revision'=>$list['revision'],'active'=>'1']);stay_input('Area Name','name','','text',true,'maxlength="120"');?><p class="settings-actions"><button class="button" type="submit">Add Area</button><button type="button" class="secondary" data-settings-cancel hidden>Cancel</button></p></form></details></section><?php else:?><p class="settings-help">You Can View These Settings But Cannot Change Them.</p><?php endif?>
